#include "HardwareBenchSession.h"
#include "qms/QmsSignatureVerifier.h"
#include <fstream>
#include <regex>
#include <sstream>
#include <stdexcept>
namespace dnxr {
namespace {
std::string readFile(const std::string& path){ std::ifstream in(path); if(!in) throw std::runtime_error("manifest not readable"); std::ostringstream ss; ss<<in.rdbuf(); return ss.str(); }
bool hasKey(const std::string& s,const std::string& k){ return s.find("\""+k+"\"")!=std::string::npos; }
std::string strv(const std::string& s,const std::string& k,const std::string& d=""){ std::regex r("\\\""+k+"\\\"\\s*:\\s*\\\"([^\\\"]*)\\\""); std::smatch m; return std::regex_search(s,m,r)?m[1].str():d; }
bool boolv(const std::string& s,const std::string& k,bool d=false){ std::regex r("\\\""+k+"\\\"\\s*:\\s*(true|false)"); std::smatch m; return std::regex_search(s,m,r)?m[1].str()=="true":d; }
float floatv(const std::string& s,const std::string& k,float d=0.0f){ std::regex r("\\\""+k+"\\\"\\s*:\\s*(-?[0-9]+(?:\\.[0-9]+)?)"); std::smatch m; return std::regex_search(s,m,r)?std::stof(m[1].str()):d; }
}
HardwareBenchSessionManifest HardwareBenchSession::dryRunManifest(){ HardwareBenchSessionManifest m; m.sessionId="HB-0.6.6-DRY-RUN"; m.hardwareSerial="loopback-bench-device"; m.firmwareVersion="bench-fw-0.1"; m.safetyKernelEnabled=true; m.emergencyStopVerified=true; m.physicalEmergencyStopVerified=true; m.traceRecordingEnabled=true; m.qmsSignaturePath="clinical_evidence/HARDWARE_BENCH_UNLOCK.signed.json"; m.qmsSignatureValid=QmsSignatureVerifier(".").verifySignedArtifact(m.qmsSignaturePath).accepted; return m; }
HardwareBenchSessionManifest HardwareBenchSession::loadManifest(const std::string& path){ auto s=readFile(path); auto m=dryRunManifest(); m.sessionId=strv(s,"session_id",m.sessionId); m.deploymentMode=runtimeDeploymentModeFromString(strv(s,"deployment_mode","HARDWARE_BENCH_NO_HUMAN")); m.humanSubjectPresent=boolv(s,"human_subject_present"); m.humanUseEnabled=boolv(s,"human_use_enabled"); m.targetType=strv(s,"target_type",m.targetType); m.targetId=strv(s,"target_id"); m.hardwareSerial=strv(s,"hardware_serial",m.hardwareSerial); m.firmwareVersion=strv(s,"firmware_version",m.firmwareVersion); m.safetyKernelEnabled=boolv(s,"safety_kernel_enabled"); m.emergencyStopVerified=boolv(s,"emergency_stop_verified"); m.physicalEmergencyStopVerified=boolv(s,"physical_emergency_stop_verified"); m.traceRecordingEnabled=boolv(s,"trace_recording_enabled"); m.activeStimulationEnabled=boolv(s,"active_stimulation_enabled"); m.maxOutputCeiling=floatv(s,"max_output_ceiling"); m.qmsSignaturePath=strv(s,"qms_signature_path"); m.trustStorePath=strv(s,"trust_store_path"); m.revocationListPath=strv(s,"revocation_list_path"); m.operatorId=strv(s,"operator_id"); m.protocolId=strv(s,"protocol_id"); if(!m.qmsSignaturePath.empty()) m.qmsSignatureValid=QmsSignatureVerifier(".").verifySignedArtifact(m.qmsSignaturePath).accepted; if(!hasKey(s,"session_id")||!hasKey(s,"deployment_mode")||!hasKey(s,"target_type")) throw std::runtime_error("manifest schema validation failed: required field missing"); return m; }
bool HardwareBenchSession::isAccepted(const HardwareBenchSessionManifest& m,std::string* r){ if(m.deploymentMode!=RuntimeDeploymentMode::HardwareBenchNoHuman && m.deploymentMode!=RuntimeDeploymentMode::PreclinicalPhantom){ if(r)*r="deployment_mode_not_allowed_for_hardware_bench"; return false;} if(m.humanSubjectPresent||m.humanUseEnabled){ if(r)*r="human_subject_present_forbidden_in_hardware_bench"; return false;} if(m.targetType!="DUMMY_LOAD"&&m.targetType!="PHANTOM"){ if(r)*r="target_must_be_dummy_load_or_phantom"; return false;} if(!m.safetyKernelEnabled){ if(r)*r="safety_kernel_required"; return false;} if(!m.emergencyStopVerified){ if(r)*r="emergency_stop_required"; return false;} if(!m.traceRecordingEnabled){ if(r)*r="trace_recorder_required"; return false;} if(!m.qmsSignaturePath.empty()&&!m.qmsSignatureValid){ if(r)*r="qms_signature_invalid"; return false;} return true; }
}
